window.SHIORI_DATA=window.SHIORI_DATA||{};SHIORI_DATA['n2_grammar']=[{"pattern":"〜をめぐって／〜をめぐる","meaning":"concerning; over (a dispute, debate or competition)","formation":"Noun + をめぐって / をめぐる + Noun","note":"Used when there is disagreement, debate or competition surrounding the topic, not for neutral \"about\".","examples":[{"ja":"新しい空港の建設をめぐって、住民の意見が分かれている。","en":"Residents' opinions are divided over the construction of the new airport."},{"ja":"予算の使い方をめぐる議論が続いている。","en":"The debate over how to use the budget is continuing."}],"id":"n2g1"},{"pattern":"〜にわたって／〜にわたる","meaning":"throughout; over (an entire period or area)","formation":"Noun (period / range) + にわたって / にわたり / にわたる + Noun","note":"Emphasizes a large scale: the whole span is covered. Often follows numbers like 三日間 or 十年.","examples":[{"ja":"会議は三日間にわたって行われた。","en":"The conference was held over three days."},{"ja":"彼は十年にわたる研究の結果を発表した。","en":"He announced the results of research spanning ten years."}],"id":"n2g2"},{"pattern":"〜において／〜における","meaning":"in; at (a place, time or field) — formal","formation":"Noun + において / における + Noun","note":"Formal equivalent of で; used in written language, speeches and official announcements.","examples":[{"ja":"卒業式は大ホールにおいて行われます。","en":"The graduation ceremony will be held in the main hall."},{"ja":"現代社会における家族の役割を考える。","en":"We consider the role of the family in modern society."}],"id":"n2g3"},{"pattern":"〜に際して","meaning":"on the occasion of; when (doing something special)","formation":"Noun / V-dictionary + に際して / に際し","note":"Formal; used for special, one-time occasions such as departures, openings or contracts.","examples":[{"ja":"出発に際して、{注意事項|ちゅういじこう}を説明します。","en":"Before departure, I will explain the points to note."},{"ja":"{契約|けいやく}に際して、{印鑑|いんかん}が必要です。","en":"A personal seal is required when signing the contract."}],"id":"n2g4"},{"pattern":"〜にあたって","meaning":"at the time of; prior to (an important undertaking)","formation":"Noun / V-dictionary + にあたって / にあたり","note":"Used before starting something important, often about preparation or formal greetings. Similar to に際して.","examples":[{"ja":"新しい生活を始めるにあたって、家具を買いそろえた。","en":"In starting my new life, I bought a full set of furniture."},{"ja":"開会にあたり、一言ご{挨拶|あいさつ}を申し上げます。","en":"On the opening of this meeting, allow me to say a few words."}],"id":"n2g5"},{"pattern":"〜に先立って","meaning":"before; prior to","formation":"Noun / V-dictionary + に先立って / に先立ち / に先立つ + Noun","note":"Something done in preparation before an event begins. Formal.","examples":[{"ja":"映画の公開に先立って、試写会が開かれた。","en":"Prior to the film's release, a preview screening was held."},{"ja":"工事を始めるに先立って、住民に説明した。","en":"Before starting construction, we explained it to the residents."}],"id":"n2g6"},{"pattern":"〜に応じて","meaning":"in accordance with; depending on","formation":"Noun + に応じて / に応じた + Noun","note":"The result changes to match the noun: ability, budget, age, demand, etc.","examples":[{"ja":"予算に応じて、プランを選ぶことができます。","en":"You can choose a plan according to your budget."},{"ja":"年齢に応じた運動をしましょう。","en":"Let's do exercise suited to our age."}],"id":"n2g7"},{"pattern":"〜に{沿|そ}って","meaning":"along; in line with; following","formation":"Noun + に沿って / に沿い / に沿った + Noun","note":"Literal (along a river or road) or figurative (following a plan, policy or someone's wishes).","examples":[{"ja":"川に{沿|そ}って{桜|さくら}の木が並んでいる。","en":"Cherry trees are lined up along the river."},{"ja":"計画に{沿|そ}って作業を進めてください。","en":"Please proceed with the work according to the plan."}],"id":"n2g8"},{"pattern":"〜に基づいて","meaning":"based on; on the basis of","formation":"Noun + に基づいて / に基づき / に基づく + Noun / に基づいた + Noun","note":"Used for rules, data, facts or experience that serve as a firm basis.","examples":[{"ja":"この映画は事実に基づいて作られた。","en":"This film was made based on actual events."},{"ja":"調査の結果に基づいて報告書を書いた。","en":"I wrote the report based on the results of the survey."}],"id":"n2g9"},{"pattern":"〜込む","meaning":"into ~; (do) deeply or thoroughly; keep on ~","formation":"V-stem + 込む","note":"Adds the idea of going inside (飛び込む, 書き込む) or of doing something deeply or for a long time (考え込む, 話し込む, 信じ込む).","examples":[{"ja":"子供がプールに飛び込んだ。","en":"The child jumped into the pool."},{"ja":"友達と夜中まで話し込んでしまった。","en":"My friend and I got so deep into conversation that we talked until midnight."}],"id":"n2g10"},{"pattern":"〜た結果","meaning":"as a result of ~; after ~ (the outcome was …)","formation":"V-た + 結果 / Noun + の + 結果","note":"States the outcome of an action or a process; common in reports and the news.","examples":[{"ja":"家族と話し合った結果、留学することにした。","en":"After talking it over with my family, I decided to study abroad."},{"ja":"調査の結果、事故の原因がわかった。","en":"The investigation revealed the cause of the accident."}],"id":"n2g11"},{"pattern":"〜を問わず","meaning":"regardless of; irrespective of","formation":"Noun + を問わず","note":"Often follows contrasting pairs or categories like 男女, 昼夜, 年齢, 経験.","examples":[{"ja":"このアルバイトは経験を問わず、だれでも応募できます。","en":"Anyone can apply for this part-time job, regardless of experience."},{"ja":"この公園には季節を問わず、多くの人が訪れる。","en":"Many people visit this park regardless of the season."}],"id":"n2g12"},{"pattern":"〜にかかわらず","meaning":"regardless of; whether or not","formation":"Noun + にかかわらず; V-dictionary + V-ない + にかかわらず","note":"Often used with opposing pairs (天気, 有無, する・しない). Do not confuse with にもかかわらず (despite).","examples":[{"ja":"天気にかかわらず、試合は行われます。","en":"The match will be held regardless of the weather."},{"ja":"参加するしないにかかわらず、返事をください。","en":"Please reply whether or not you will participate."}],"id":"n2g13"},{"pattern":"〜にもかかわらず","meaning":"despite; in spite of; although","formation":"Noun / Plain form + にもかかわらず (na-adj / noun: である optional)","note":"Shows a result against expectation, often with surprise or criticism. Formal.","examples":[{"ja":"雨にもかかわらず、たくさんの人が集まった。","en":"Despite the rain, a lot of people gathered."},{"ja":"彼は熱があるにもかかわらず、仕事に来た。","en":"He came to work even though he had a fever."}],"id":"n2g14"},{"pattern":"〜に反して","meaning":"contrary to; against","formation":"Noun + に反して / に反する + Noun","note":"Usually with 予想, 期待, 意志 or 規則: the outcome goes against expectations or rules.","examples":[{"ja":"予想に反して、試験は簡単だった。","en":"Contrary to expectations, the exam was easy."},{"ja":"親の期待に反して、彼は大学に進学しなかった。","en":"Contrary to his parents' hopes, he did not go on to university."}],"id":"n2g15"},{"pattern":"〜てはならない","meaning":"must not ~ (formal rules and moral statements)","formation":"V-て + はならない","note":"A formal version of 〜てはいけない, used for rules, warnings and moral statements.","examples":[{"ja":"試験中に話してはならない。","en":"You must not talk during the exam."},{"ja":"戦争の悲劇を忘れてはならない。","en":"We must never forget the tragedy of war."}],"id":"n2g16"},{"pattern":"〜のもとで／〜のもとに","meaning":"under (guidance, influence or a condition)","formation":"Noun + のもとで / のもとに","note":"Used with people of authority or conditions, e.g. 先生のもとで, 〜という条件のもとで.","examples":[{"ja":"有名な先生のもとでピアノを学んだ。","en":"I studied piano under a famous teacher."},{"ja":"両親の愛情のもとで、子供たちは元気に育った。","en":"Under their parents' love, the children grew up healthy."}],"id":"n2g17"},{"pattern":"〜限りだ","meaning":"extremely ~; I feel so ~ (the speaker's strong feeling)","formation":"い-adj + 限りだ / な-adj + な + 限りだ","note":"Expresses the speaker's own strong emotion: 嬉しい限りだ, 心細い限りだ. Different from 〜限り (as long as).","examples":[{"ja":"皆様にお祝いしていただき、{嬉|うれ}しい限りです。","en":"I'm overjoyed to receive everyone's congratulations."},{"ja":"一人で外国に住むのは心細い限りだ。","en":"Living abroad on my own makes me feel terribly lonely."}],"id":"n2g18"},{"pattern":"〜を{契機|けいき}に","meaning":"with ... as a turning point; taking the occasion of","formation":"Noun / V-た + の + を契機に(して) / を契機として","note":"A more formal version of をきっかけに; often for major life or social events.","examples":[{"ja":"結婚を{契機|けいき}に、彼女は仕事を辞めた。","en":"She quit her job when she got married."},{"ja":"オリンピックを{契機|けいき}として、町の交通が整備された。","en":"The Olympics became the occasion for improving the city's transportation."}],"id":"n2g19"},{"pattern":"〜を抜きにして／〜抜きで","meaning":"without; leaving out","formation":"Noun + を抜きにして(は) / 抜きで / 抜きの + Noun","note":"を抜きにしては〜ない means \"cannot ... without A\". 抜きで simply means \"without\".","examples":[{"ja":"{冗談|じょうだん}は抜きにして、{真剣|しんけん}に話し合いましょう。","en":"Joking aside, let's talk seriously."},{"ja":"彼の協力を抜きにしては、この計画は{成功|せいこう}しなかった。","en":"Without his cooperation, this plan would not have succeeded."},{"ja":"今朝は朝ご飯抜きで会社に来た。","en":"This morning I came to work without breakfast."}],"id":"n2g20"},{"pattern":"〜はともかく(として)","meaning":"setting aside; regardless of","formation":"Noun + はともかく(として)","note":"Puts A aside as less important for now and focuses on B.","examples":[{"ja":"味はともかく、この店は値段が安い。","en":"Taste aside, this restaurant is cheap."},{"ja":"結果はともかく、最後まで{頑張|がんば}ったことが大切だ。","en":"Regardless of the result, what matters is that you tried your best to the end."}],"id":"n2g21"},{"pattern":"〜は別として","meaning":"apart from; except for; leaving aside","formation":"Noun + は別として; 〜かどうかは別として","note":"Excludes A from consideration; often used as 〜かどうかは別として.","examples":[{"ja":"好きかどうかは別として、一度食べてみてください。","en":"Whether you like it or not, please try eating it once."},{"ja":"一部の学生は別として、ほとんどの人が合格した。","en":"Apart from a few students, almost everyone passed."}],"id":"n2g22"},{"pattern":"〜はもとより","meaning":"not only ... but also; let alone (formal)","formation":"Noun + はもとより","note":"A more formal, written version of はもちろん, with the same meaning.","examples":[{"ja":"この歌手は国内はもとより、海外でも人気がある。","en":"This singer is popular not only in Japan but also overseas."},{"ja":"この映画は子供はもとより、大人も楽しめる。","en":"Adults, not to mention children, can enjoy this movie."}],"id":"n2g23"},{"pattern":"〜のみならず","meaning":"not only ... but also (formal)","formation":"Noun / Plain form + のみならず (na-adj / noun: である + のみならず)","note":"The written equivalent of だけでなく; usually followed by も.","examples":[{"ja":"この問題は日本のみならず、世界中の問題だ。","en":"This is a problem not only for Japan but for the whole world."},{"ja":"彼は勉強のみならず、スポーツも得意だ。","en":"He is good not only at studying but also at sports."}],"id":"n2g24"},{"pattern":"〜に限らず","meaning":"not limited to; not only","formation":"Noun + に限らず","note":"The statement applies more widely than just A.","examples":[{"ja":"この歌は若者に限らず、多くの人に愛されている。","en":"This song is loved by many people, not only young people."},{"ja":"日曜日に限らず、平日も営業しています。","en":"We are open not only on Sundays but also on weekdays."}],"id":"n2g25"},{"pattern":"〜に限って","meaning":"only when; of all times/people; especially","formation":"Noun + に限って","note":"Often expresses frustration that bad luck strikes at the worst time, or strong trust: うちの子に限って.","examples":[{"ja":"急いでいる時に限って、電車が遅れる。","en":"The train is always late precisely when I'm in a hurry."},{"ja":"うちの子に限って、そんなことをするはずがない。","en":"My child, of all people, would never do such a thing."}],"id":"n2g26"},{"pattern":"〜に限り","meaning":"only; limited to","formation":"Noun + に限り","note":"Common in notices and advertisements: a special condition applies only to A.","examples":[{"ja":"先着100名に限り、無料でプレゼントを差し上げます。","en":"Only the first 100 people will receive a free gift."},{"ja":"本日に限り、全品半額です。","en":"Today only, everything is half price."}],"id":"n2g27"},{"pattern":"〜限り","meaning":"as long as; as far as; to the limit of","formation":"V-dictionary / V-ている / V-ない / い-adj / na-adj + な (である) / Noun + である + 限り","note":"A condition that holds while A is true. Also used as できる限り (as much as possible) and 知る限り.","examples":[{"ja":"体が元気な限り、働き続けたい。","en":"As long as I'm healthy, I want to keep working."},{"ja":"私の知る限り、彼はうそをつく人ではない。","en":"As far as I know, he isn't someone who tells lies."},{"ja":"できる限り協力します。","en":"I'll cooperate as much as I can."}],"id":"n2g28"},{"pattern":"〜にかけては","meaning":"when it comes to; in terms of (skill)","formation":"Noun + にかけては / にかけても","note":"Praises someone's ability in a particular field; followed by a strong positive evaluation.","examples":[{"ja":"料理の腕にかけては、母に勝てる人はいない。","en":"When it comes to cooking skills, no one can beat my mother."},{"ja":"足の速さにかけては、彼はクラスで一番だ。","en":"When it comes to running speed, he's the best in the class."}],"id":"n2g29"},{"pattern":"〜にしても","meaning":"even if; even though; granted that","formation":"Noun / Plain form + にしても","note":"Accepts A, but states a contrary opinion or reservation in B.","examples":[{"ja":"忙しいにしても、電話ぐらいできるでしょう。","en":"Even if you're busy, you could at least call."},{"ja":"{冗談|じょうだん}にしても、そんなことを言ってはいけない。","en":"Even as a joke, you shouldn't say such things."}],"id":"n2g30"},{"pattern":"〜にしろ〜にしろ／〜にせよ〜にせよ","meaning":"whether ... or ...; either way","formation":"Noun / Plain form + にしろ + Noun / Plain form + にしろ","note":"Whichever alternative is chosen, the conclusion is the same. にせよ is more formal.","examples":[{"ja":"行くにしろ行かないにしろ、早く連絡してください。","en":"Whether you go or not, please let me know soon."},{"ja":"肉にせよ魚にせよ、{新鮮|しんせん}なものを選んだほうがいい。","en":"Whether it's meat or fish, it's better to choose fresh ones."}],"id":"n2g31"},{"pattern":"〜からいうと／〜からいって","meaning":"from the point of view of; judging from","formation":"Noun + からいうと / からいえば / からいって","note":"Judges from a standpoint or criterion. Not attached directly to a person; use からすると for people.","examples":[{"ja":"私の経験からいうと、この方法が一番早い。","en":"From my experience, this method is the fastest."},{"ja":"実力からいって、彼が優勝するだろう。","en":"Judging from his ability, he will probably win."}],"id":"n2g32"},{"pattern":"〜からすると／〜からすれば","meaning":"from the perspective of; judging from","formation":"Noun + からすると / からすれば","note":"Can take a person (親からすれば) or a piece of evidence on which a judgment is based.","examples":[{"ja":"親からすれば、子供はいつまでも子供だ。","en":"From a parent's point of view, children are always children."},{"ja":"あの話し方からすると、彼は関西の人だろう。","en":"Judging from the way he talks, he's probably from Kansai."}],"id":"n2g33"},{"pattern":"〜からして","meaning":"judging from; starting with (even the most basic)","formation":"Noun + からして","note":"\"Judging from\", or \"even A\" as a typical example, implying the rest is the same.","examples":[{"ja":"この映画はタイトルからしておもしろそうだ。","en":"Judging from the title alone, this movie looks interesting."},{"ja":"彼は{挨拶|あいさつ}の仕方からして失礼だ。","en":"He's rude, starting with the way he greets people."}],"id":"n2g34"},{"pattern":"〜から見ると／〜から見れば","meaning":"from the viewpoint of; judging from","formation":"Noun + から見ると / から見れば / から見て","note":"The viewpoint of a person, or a basis for judgment; similar to からすると.","examples":[{"ja":"子供から見ると、大人の世界は不思議なものだ。","en":"From a child's point of view, the adult world is a strange thing."},{"ja":"空の様子から見ると、明日は雨だろう。","en":"Judging from the look of the sky, it will probably rain tomorrow."}],"id":"n2g35"},{"pattern":"〜にしたら／〜にすれば","meaning":"from the standpoint of (someone)","formation":"Noun (person) + にしたら / にすれば / にしてみれば","note":"Imagining the feelings or position of someone other than the speaker.","examples":[{"ja":"母にしたら、娘が遠くへ行くのは{寂|さび}しいだろう。","en":"For my mother, it must be lonely to have her daughter go far away."},{"ja":"学生にすれば、宿題は少ないほうがいい。","en":"From the students' point of view, less homework is better."}],"id":"n2g36"},{"pattern":"〜上","meaning":"from the standpoint of; in terms of; -wise","formation":"Noun + 上 / 上の + Noun / 上は","note":"Attaches to nouns like 健康, 教育, 法律, 歴史, 仕事: \"from a ... point of view\".","examples":[{"ja":"夜遅くまでゲームをするのは健康上よくない。","en":"Playing games until late at night is bad for your health."},{"ja":"この映画は教育上問題があると言われている。","en":"This film is said to be problematic from an educational standpoint."}],"id":"n2g37"},{"pattern":"〜につき","meaning":"due to; because of (notices); per","formation":"Noun + につき","note":"Formal. Seen on signs (工事中につき) or meaning \"per\" (一人につき).","examples":[{"ja":"工事中につき、通行止めです。","en":"Road closed due to construction."},{"ja":"参加費は一人につき千円です。","en":"The participation fee is 1,000 yen per person."}],"id":"n2g38"},{"pattern":"〜につけ","meaning":"whenever; every time","formation":"V-dictionary + につけ; 〜につけ〜につけ","note":"Often with 見る, 聞く, 思う: each time, a feeling naturally arises. Also: 何かにつけ, いいにつけ悪いにつけ.","examples":[{"ja":"この写真を見るにつけ、子供の{頃|ころ}を思い出す。","en":"Whenever I see this photo, I remember my childhood."},{"ja":"いいにつけ悪いにつけ、彼はみんなの注目を集める。","en":"For better or worse, he always attracts everyone's attention."}],"id":"n2g39"},{"pattern":"〜げ","meaning":"seeming; looking (as if)","formation":"い-adj stem / な-adj stem + げ (+ な + Noun / + に)","note":"Describes how someone appears to feel: 悲しげ, 寂しげ, 楽しげ, 不安げ. Mostly written.","examples":[{"ja":"彼女は悲しげな顔で窓の外を見ていた。","en":"She was looking out the window with a sad expression."},{"ja":"公園で子供たちが楽しげに遊んでいる。","en":"The children are playing happily in the park."}],"id":"n2g40"},{"pattern":"〜ねばならない","meaning":"must ~; have to ~ (formal, written)","formation":"V-ない stem + ねばならない (する → せねばならない)","note":"A formal, written version of 〜なければならない. 〜ねば alone = 〜なければ.","examples":[{"ja":"国民は法律を守らねばならない。","en":"Citizens must obey the law."},{"ja":"この問題は早急に解決せねばならない。","en":"This problem must be solved urgently."}],"id":"n2g41"},{"pattern":"〜ぬく","meaning":"to do to the very end; thoroughly","formation":"V-ます stem + ぬく","note":"Persevering through difficulty until the end: 走りぬく, 考えぬく, やりぬく.","examples":[{"ja":"足が痛かったが、彼は最後まで走りぬいた。","en":"His leg hurt, but he ran all the way to the end."},{"ja":"考えぬいた結果、会社を辞めることにした。","en":"After thinking it through thoroughly, I decided to quit my job."}],"id":"n2g42"},{"pattern":"〜得る／〜得る","meaning":"can; it is possible to","formation":"V-ます stem + 得る (える / うる); negative: 得ない (えない)","note":"Expresses possibility, not personal ability. The negative is always えない, as in ありえない.","examples":[{"ja":"大きな地震はいつでも起こり得る。","en":"A big earthquake could happen at any time."},{"ja":"そんなことはあり得ない。","en":"That's impossible."}],"id":"n2g43"},{"pattern":"〜かねる","meaning":"cannot; be unable to (polite refusal)","formation":"V-ます stem + かねる","note":"Polite refusal common in business: わかりかねます, お答えしかねます. Note: the meaning is negative.","examples":[{"ja":"申し{訳|わけ}ありませんが、その質問にはお答えしかねます。","en":"I'm sorry, but I'm unable to answer that question."},{"ja":"彼の意見には賛成しかねる。","en":"I can't agree with his opinion."}],"id":"n2g44"},{"pattern":"〜かねない","meaning":"might; could (lead to something bad)","formation":"V-ます stem + かねない","note":"Despite the negative form, means a bad outcome is possible.","examples":[{"ja":"そんなに無理をすると、病気になりかねない。","en":"If you push yourself that hard, you could get sick."},{"ja":"スピードを出しすぎると、事故を起こしかねない。","en":"Driving too fast could cause an accident."}],"id":"n2g45"},{"pattern":"〜がたい","meaning":"hard to; difficult to (emotionally)","formation":"V-ます stem + がたい","note":"Psychological difficulty: 信じがたい, 許しがたい, 忘れがたい. Not for physical difficulty (use にくい).","examples":[{"ja":"彼がそんなことをしたとは信じがたい。","en":"It's hard to believe that he did such a thing."},{"ja":"あの旅行は忘れがたい思い出になった。","en":"That trip became an unforgettable memory."}],"id":"n2g46"},{"pattern":"〜おそれがある","meaning":"there is a risk that; might (bad outcome)","formation":"Noun + の / V-dictionary + おそれがある","note":"A formal warning about a possible bad outcome; common in news and weather reports.","examples":[{"ja":"台風が上陸するおそれがあります。","en":"There is a risk that the typhoon will make landfall."},{"ja":"この薬は眠くなるおそれがあるので、運転の前に飲まないでください。","en":"This medicine may cause drowsiness, so do not take it before driving."}],"id":"n2g47"},{"pattern":"〜っこない","meaning":"no way; absolutely cannot","formation":"V-ます stem + っこない","note":"Casual, strong denial of possibility; mostly with わかる, できる, 勝つ.","examples":[{"ja":"こんな難しい問題、子供にわかりっこない。","en":"There's no way a child could understand such a difficult problem."},{"ja":"一日でこの仕事を全部やるなんて、できっこないよ。","en":"There's no way I can do all this work in one day."}],"id":"n2g48"},{"pattern":"〜つつある","meaning":"is in the process of; is gradually","formation":"V-ます stem + つつある","note":"Written style. Ongoing gradual change, emphasizing progress in one direction.","examples":[{"ja":"地球の気温は上がりつつある。","en":"The earth's temperature is gradually rising."},{"ja":"町は少しずつ元の{姿|すがた}を取り戻しつつある。","en":"The town is little by little getting back to how it used to be."}],"id":"n2g49"},{"pattern":"〜つつ(も)","meaning":"while; although","formation":"V-ます stem + つつ / つつも","note":"つつ = while (a formal ながら, same subject). つつも = although, admitting something contradictory.","examples":[{"ja":"体に悪いと知りつつも、たばこがやめられない。","en":"Although I know it's bad for my health, I can't quit smoking."},{"ja":"景色を楽しみつつ、ゆっくり歩いた。","en":"I walked slowly while enjoying the scenery."}],"id":"n2g50"},{"pattern":"〜次第","meaning":"as soon as","formation":"V-ます stem / Noun (action) + 次第","note":"Polite, business style. The second clause is a deliberate future action, not a past event.","examples":[{"ja":"結果がわかり次第、ご連絡いたします。","en":"We will contact you as soon as we know the results."},{"ja":"準備ができ次第、出発しましょう。","en":"Let's leave as soon as we're ready."}],"id":"n2g51"},{"pattern":"〜次第だ／〜次第で","meaning":"depends on; depending on","formation":"Noun + 次第だ / 次第で(は)","note":"The outcome is decided by A: 天気次第, あなた次第, 努力次第.","examples":[{"ja":"{成功|せいこう}するかどうかは、あなたの努力次第だ。","en":"Whether you succeed or not depends on your efforts."},{"ja":"天気次第では、試合が中止になるかもしれない。","en":"Depending on the weather, the game might be canceled."}],"id":"n2g52"},{"pattern":"〜か〜ないかのうちに","meaning":"no sooner than; just as; barely","formation":"V-dictionary / V-た + か + V-ない + かのうちに","note":"B happens almost at the same moment as A, before A is even complete.","examples":[{"ja":"ベルが鳴るか鳴らないかのうちに、学生たちは教室を飛び出した。","en":"The students rushed out of the classroom almost before the bell had rung."},{"ja":"弟は布団に入ったか入らないかのうちに、眠ってしまった。","en":"My little brother fell asleep the moment he got into bed."}],"id":"n2g53"},{"pattern":"〜かと思うと／〜かと思ったら","meaning":"just when ...; no sooner had ... than","formation":"V-た + かと思うと / かと思ったら","note":"A quick, surprising change observed by the speaker. Not used for the speaker's own actions.","examples":[{"ja":"空が暗くなったかと思うと、{激|はげ}しい雨が降ってきた。","en":"No sooner had the sky gone dark than heavy rain started to fall."},{"ja":"息子は帰ってきたかと思ったら、すぐに遊びに出かけた。","en":"My son had barely come home when he went out to play again."}],"id":"n2g54"},{"pattern":"〜た上で","meaning":"after (doing ... then); upon","formation":"V-た / Noun + の + 上で","note":"Do A first, then do B based on it: 相談した上で決める. Often for careful decisions.","examples":[{"ja":"家族と相談した上で、お返事します。","en":"I'll give you my answer after discussing it with my family."},{"ja":"内容をよく確認の上で、サインしてください。","en":"Please sign after carefully checking the contents."}],"id":"n2g55"},{"pattern":"〜上で(は)","meaning":"in (doing); for the purpose of; when it comes to","formation":"V-dictionary / Noun + の + 上で(は) / 上での + Noun","note":"\"In the process of / for doing A\": 生活する上で, 仕事の上で. Different from た上で (after).","examples":[{"ja":"日本で生活する上で、日本語は欠かせない。","en":"Japanese is essential for living in Japan."},{"ja":"外国語を学ぶ上で大切なのは、毎日続けることだ。","en":"What matters in learning a foreign language is keeping at it every day."}],"id":"n2g56"},{"pattern":"〜あげく","meaning":"after a lot of ...; in the end (a bad result)","formation":"V-た / Noun + の + あげく(に)","note":"After a long, troublesome process, it ends in an unfortunate or frustrating result.","examples":[{"ja":"さんざん迷ったあげく、何も買わずに帰った。","en":"After agonizing over it for ages, I went home without buying anything."},{"ja":"長い議論のあげく、計画は中止になった。","en":"After a long debate, the plan was eventually canceled."}],"id":"n2g57"},{"pattern":"〜末(に)","meaning":"after; finally (after much effort)","formation":"V-た / Noun + の + 末(に) / 末の + Noun","note":"After long effort or thought, a result is reached. Can be positive or neutral, unlike あげく.","examples":[{"ja":"何度も話し合った末に、結論が出た。","en":"After discussing it many times, we finally reached a conclusion."},{"ja":"長い練習の末、ついに試合に勝った。","en":"After long practice, we finally won a match."}],"id":"n2g58"},{"pattern":"〜あまり","meaning":"so much that; out of too much","formation":"V-dictionary / V-た / Noun + の / な-adj + な + あまり(に)","note":"An excessive emotion or state leads to an unusual or undesirable result.","examples":[{"ja":"心配のあまり、夜も眠れなかった。","en":"I was so worried that I couldn't sleep at night."},{"ja":"{緊張|きんちょう}するあまり、自分の名前を言い間違えてしまった。","en":"I was so nervous that I said my own name wrong."}],"id":"n2g59"},{"pattern":"〜ばかりに","meaning":"simply because; just because (regret)","formation":"Plain form (na-adj + な / である, noun + である) + ばかりに","note":"One cause leads to a bad result, expressing regret. 〜たいばかりに = out of a strong wish to.","examples":[{"ja":"私が余計なことを言ったばかりに、彼女を怒らせてしまった。","en":"Just because I said something unnecessary, I made her angry."},{"ja":"寝坊したばかりに、大事な試験を受けられなかった。","en":"Simply because I overslept, I couldn't take an important exam."}],"id":"n2g60"},{"pattern":"〜だけあって","meaning":"as expected of; precisely because (positive)","formation":"Plain form (na-adj + な, noun) + だけあって / だけのことはある","note":"The result matches what A would lead you to expect; usually admiring. Often with さすが.","examples":[{"ja":"十年も日本に住んでいるだけあって、彼は日本語がぺらぺらだ。","en":"As you'd expect from someone who has lived in Japan for ten years, he is fluent in Japanese."},{"ja":"さすが有名な店だけあって、料理がとてもおいしい。","en":"As expected of a famous restaurant, the food is delicious."}],"id":"n2g61"},{"pattern":"〜だけに","meaning":"precisely because; all the more because","formation":"Plain form (na-adj + な, noun) + だけに","note":"Because of A, B is natural or even stronger than usual. Can be positive or negative.","examples":[{"ja":"期待していただけに、失敗したときはがっかりした。","en":"Precisely because I had high hopes, I was all the more disappointed when it failed."},{"ja":"彼は若いだけに、覚えるのが早い。","en":"Being young, he learns things quickly."}],"id":"n2g62"},{"pattern":"〜からには","meaning":"since; now that (one must)","formation":"Plain form (na-adj / noun + である) + からには","note":"Since A is the case, B (determination, duty) must follow; often with なければならない, つもりだ, たい.","examples":[{"ja":"約束したからには、必ず守らなければならない。","en":"Since you promised, you must keep your word."},{"ja":"試合に出るからには、優勝を目指したい。","en":"Now that I'm entering the competition, I want to aim to win."}],"id":"n2g63"},{"pattern":"〜以上(は)","meaning":"since; now that","formation":"Plain form (na-adj / noun + である) + 以上(は)","note":"Like からには: given A, B is a natural duty or conclusion.","examples":[{"ja":"学生である以上、勉強するのは当然だ。","en":"Since you're a student, it's only natural that you study."},{"ja":"引き受けた以上は、最後までやるつもりだ。","en":"Now that I've taken it on, I intend to see it through."}],"id":"n2g64"},{"pattern":"〜ものだから／〜もので","meaning":"because; since (excuse or explanation)","formation":"Plain form (na-adj + な, noun + な) + ものだから / もので","note":"Gives a personal reason or excuse. Casual: もんだから. Not followed by commands or requests.","examples":[{"ja":"道が混んでいたものだから、遅れてしまいました。","en":"The roads were crowded, so I ended up being late."},{"ja":"急な用事ができたもので、参加できませんでした。","en":"Something urgent came up, so I couldn't attend."}],"id":"n2g65"},{"pattern":"〜ことだから","meaning":"since it's (someone); knowing (someone)","formation":"Noun (person) + の + ことだから","note":"Predicts behavior based on what you know about someone's character.","examples":[{"ja":"真面目な彼のことだから、きっと時間どおりに来るだろう。","en":"Knowing how serious he is, he'll surely come on time."},{"ja":"子供のことだから、すぐに忘れるでしょう。","en":"Kids being kids, they'll probably forget about it soon."}],"id":"n2g66"},{"pattern":"〜ものの","meaning":"although; but","formation":"Plain form (na-adj + な / である, noun + である) + ものの","note":"Admits A, but B does not go as one would expect. Written style.","examples":[{"ja":"車の{免許|めんきょ}は取ったものの、ほとんど運転していない。","en":"Although I got my driver's license, I hardly ever drive."},{"ja":"新しいパソコンを買ったものの、使い方がよくわからない。","en":"I bought a new computer, but I don't really know how to use it."}],"id":"n2g67"},{"pattern":"〜とはいうものの","meaning":"although (it is said that); even so","formation":"Plain form / Noun + とはいうものの; sentence-initial とはいうものの","note":"Admits a general statement but points out that the reality is different.","examples":[{"ja":"三月に入ったとはいうものの、まだ寒い日が続いている。","en":"Although it's already March, the cold days are continuing."},{"ja":"日本語を三年勉強したとはいうものの、まだ敬語は苦手だ。","en":"Although I've studied Japanese for three years, I'm still not good at honorific language."}],"id":"n2g68"},{"pattern":"〜どころか","meaning":"far from; let alone; on the contrary","formation":"Plain form (na-adj (な), noun) + どころか","note":"The reality is the opposite of A, or goes far beyond it.","examples":[{"ja":"雨はやむどころか、ますます強くなった。","en":"Far from stopping, the rain got even heavier."},{"ja":"彼は漢字どころか、ひらがなも書けない。","en":"He can't even write hiragana, let alone kanji."}],"id":"n2g69"},{"pattern":"〜どころではない","meaning":"not the time for; out of the question","formation":"Noun / V-dictionary + どころではない / どころじゃない","note":"Circumstances make A impossible right now.","examples":[{"ja":"仕事が忙しくて、旅行どころではない。","en":"I'm so busy with work that a trip is out of the question."},{"ja":"明日は試験なので、遊ぶどころじゃない。","en":"I have an exam tomorrow, so this is no time to be playing."}],"id":"n2g70"},{"pattern":"〜というものだ","meaning":"that's what ... is; that is (truly)","formation":"Plain form / Noun + というものだ","note":"The speaker's firm judgment about the true nature of something; often critical.","examples":[{"ja":"人の日記を勝手に読むなんて、失礼というものだ。","en":"Reading someone's diary without permission is just plain rude."},{"ja":"困っている人を助けるのが、本当の友情というものだ。","en":"Helping someone in trouble is what true friendship is."}],"id":"n2g71"},{"pattern":"〜というものではない／〜というものでもない","meaning":"it's not necessarily the case that","formation":"Plain form + というものではない / というものでもない","note":"Rejects an overly simple view; often after 〜ばいい or 〜ほどいい.","examples":[{"ja":"お金があれば幸せになれるというものではない。","en":"Having money doesn't necessarily make you happy."},{"ja":"練習は長くやればいいというものでもない。","en":"It isn't true that the longer you practice, the better."}],"id":"n2g72"},{"pattern":"〜ものか","meaning":"as if ...!; definitely not","formation":"Plain form (na-adj + な, noun + な) + ものか / もんか","note":"Strong denial or refusal. Casual: もんか; polite: ものですか.","examples":[{"ja":"あんな店、二度と行くものか。","en":"I'll never go to that shop again!"},{"ja":"こんなに難しい問題、わかるもんか。","en":"As if anyone could understand such a hard problem!"}],"id":"n2g73"},{"pattern":"〜ものがある","meaning":"there is something (about it); really is","formation":"V-dictionary / い-adj / な-adj + な + ものがある","note":"Expresses the speaker's strong impression of a quality that is felt.","examples":[{"ja":"彼の歌には人の心を動かすものがある。","en":"There is something in his singing that moves people's hearts."},{"ja":"毎日同じ仕事を続けるのは、つらいものがある。","en":"Doing the same job every day really is tough."}],"id":"n2g74"},{"pattern":"〜ものなら","meaning":"if (one could); if ... (then something bad)","formation":"V-potential + ものなら; V-volitional + ものなら","note":"Potential: a wish for something hard to do (できるものなら). Volitional: if you dare, something bad will follow.","examples":[{"ja":"できるものなら、もう一度学生時代に戻りたい。","en":"If I could, I'd like to go back to my school days once more."},{"ja":"授業に遅れようものなら、先生にひどく{叱|しか}られる。","en":"If you're ever late for class, the teacher scolds you terribly."}],"id":"n2g75"},{"pattern":"〜ことに","meaning":"(much) to my ...; it is ... that","formation":"V-た / い-adj / な-adj + な + ことに","note":"An emotion word (驚いた, 残念な, うれしい) comes first, expressing the speaker's feeling about the fact.","examples":[{"ja":"{驚|おどろ}いたことに、彼は一人でその山に登ったそうだ。","en":"Surprisingly, I hear he climbed that mountain alone."},{"ja":"残念なことに、旅行は中止になった。","en":"Unfortunately, the trip was canceled."}],"id":"n2g76"},{"pattern":"〜ことなく","meaning":"without (doing)","formation":"V-dictionary + ことなく","note":"A formal version of ないで / ずに, often emphasizing persistence: 休むことなく.","examples":[{"ja":"彼は一日も休むことなく、会社に通い続けた。","en":"He kept going to work without taking a single day off."},{"ja":"失敗を恐れることなく、{挑戦|ちょうせん}してください。","en":"Please take on the challenge without fearing failure."}],"id":"n2g77"},{"pattern":"〜ないことには","meaning":"unless; if ... not","formation":"V-ない / い-adj (くない) / な-adj, Noun + でない + ことには","note":"Without A, B cannot happen; B is usually negative (できない, わからない).","examples":[{"ja":"実際に会ってみないことには、どんな人かわからない。","en":"Unless I actually meet them, I can't tell what kind of person they are."},{"ja":"社長が来ないことには、会議を始められない。","en":"We can't start the meeting until the president arrives."}],"id":"n2g78"},{"pattern":"〜ずにはいられない","meaning":"can't help (doing)","formation":"V-ない stem + ずにはいられない (する → せずにはいられない)","note":"An urge or emotion that can't be held back; mostly about the speaker's own feelings.","examples":[{"ja":"その映画を見て、泣かずにはいられなかった。","en":"I couldn't help crying when I watched that movie."},{"ja":"彼の話を聞くと、笑わずにはいられない。","en":"Whenever I hear his stories, I can't help laughing."}],"id":"n2g79"},{"pattern":"〜ざるを得ない","meaning":"have no choice but to; cannot help but","formation":"V-ない stem + ざるを得ない (する → せざるを得ない)","note":"Forced by circumstances to do something one does not want to do. Formal.","examples":[{"ja":"雨がひどいので、試合は中止せざるを得ない。","en":"The rain is so heavy that we have no choice but to cancel the game."},{"ja":"上司の命令なので、行かざるを得ない。","en":"It's my boss's order, so I have no choice but to go."}],"id":"n2g80"},{"pattern":"〜にほかならない","meaning":"nothing but; none other than","formation":"Noun / Plain form + にほかならない; 〜からにほかならない","note":"Strongly asserts that A is exactly the reason or truth. Formal.","examples":[{"ja":"彼が{成功|せいこう}したのは、努力の結果にほかならない。","en":"His success is nothing but the result of hard work."},{"ja":"親が{厳|きび}しく言うのは、子供を愛しているからにほかならない。","en":"Parents speak strictly for no other reason than that they love their children."}],"id":"n2g81"},{"pattern":"〜に越したことはない","meaning":"it's best to; nothing is better than","formation":"V-dictionary / い-adj / な-adj / Noun + に越したことはない","note":"Common-sense advice: A is best, even if it isn't strictly necessary.","examples":[{"ja":"用心するに越したことはない。","en":"It never hurts to be careful."},{"ja":"旅行の荷物は軽いに越したことはない。","en":"When traveling, the lighter your luggage, the better."}],"id":"n2g82"},{"pattern":"〜まい","meaning":"will not; probably not","formation":"V-dictionary + まい (ru-verbs also V-ます stem + まい; する → するまい / すまい; 来る → 来るまい / 来まい)","note":"Written style. Strong negative intention (二度と〜まい) or a negative guess (〜のではあるまいか).","examples":[{"ja":"もう二度とあの店には行くまい。","en":"I will never go to that shop again."},{"ja":"この空なら、雨は降るまい。","en":"With a sky like this, it probably won't rain."}],"id":"n2g83"},{"pattern":"〜かのようだ","meaning":"as if; as though","formation":"Plain form (na-adj / noun + である) + かのようだ / かのように / かのような + Noun","note":"Compares to something that is not actually true. Common in written descriptions.","examples":[{"ja":"彼は何も知らないかのような顔をしている。","en":"He's acting as if he doesn't know anything."},{"ja":"今日は暖かくて、春が来たかのようだ。","en":"It's so warm today, it's as if spring has come."}],"id":"n2g84"},{"pattern":"〜も〜ば〜も","meaning":"both ... and ...; neither ... nor ...","formation":"Noun + も + V / Adj -ば (na-adj / noun: なら) + Noun + も","note":"Lists two similar points that are both positive or both negative.","examples":[{"ja":"彼は英語も話せれば、中国語も話せる。","en":"He can speak both English and Chinese."},{"ja":"この部屋は日当たりもよければ、駅にも近い。","en":"This apartment gets plenty of sunlight and is close to the station, too."}],"id":"n2g85"},{"pattern":"〜やら〜やら","meaning":"things like ... and ...; what with ... and ...","formation":"Noun / V-dictionary / い-adj + やら + Noun / V-dictionary / い-adj + やら","note":"Lists examples, often implying the situation was chaotic or overwhelming.","examples":[{"ja":"引っ越しの準備やら仕事やらで、毎日忙しい。","en":"What with preparing for the move and work, I'm busy every day."},{"ja":"財布をなくして、悲しいやら腹が立つやら、大変だった。","en":"I lost my wallet, and between feeling sad and angry, it was awful."}],"id":"n2g86"},{"pattern":"〜といった","meaning":"such as; like (listing)","formation":"Noun + や + Noun + といった + Noun","note":"Lists representative examples, followed by the general category.","examples":[{"ja":"京都や{奈良|なら}といった古い町が好きだ。","en":"I like old cities such as Kyoto and Nara."},{"ja":"この店では、{寿司|すし}や天ぷらといった日本料理が食べられる。","en":"At this restaurant you can eat Japanese food such as sushi and tempura."}],"id":"n2g87"},{"pattern":"〜もかまわず","meaning":"without worrying about; regardless of","formation":"Noun / Plain form + の + もかまわず","note":"Doing something without caring about other people or circumstances; often critical.","examples":[{"ja":"彼女は人目もかまわず泣き出した。","en":"She burst into tears without caring who was watching."},{"ja":"子供は服が汚れるのもかまわず、雨の中で遊んでいる。","en":"The child is playing in the rain, not caring that his clothes are getting dirty."}],"id":"n2g88"},{"pattern":"〜に過ぎない","meaning":"merely; nothing more than","formation":"Noun / Plain form + に過ぎない","note":"Emphasizes that something is small or unimportant.","examples":[{"ja":"これは私の個人的な意見に過ぎない。","en":"This is merely my personal opinion."},{"ja":"合格したのはクラスの半分に過ぎなかった。","en":"Only half of the class passed."}],"id":"n2g89"},{"pattern":"〜ところを見ると","meaning":"judging from (the fact that) ~; seeing that ~","formation":"Plain form (な-adj + な / Noun + である) + ところを見ると / ところを見れば","note":"Draws a conclusion from something you can see. The second half is a guess: 〜らしい, 〜ようだ, 〜に違いない.","examples":[{"ja":"彼が笑っているところを見ると、試験はうまくいったらしい。","en":"Seeing him smiling, the exam must have gone well."},{"ja":"{誰|だれ}も来ないところを見ると、今日の会議は中止になったようだ。","en":"Judging from the fact that nobody's come, today's meeting seems to have been cancelled."}],"id":"n2g90"},{"pattern":"〜ばかりだ","meaning":"keeps ~ing; just keeps getting more (usually worse)","formation":"V-dictionary form + ばかりだ","note":"A change that keeps going in one direction, usually a bad one. Close to 〜一方だ.","examples":[{"ja":"物価は上がるばかりだ。","en":"Prices just keep going up."},{"ja":"父の病状は悪くなるばかりで、家族は心配している。","en":"My father's condition only keeps getting worse, and the family is worried."}],"id":"n2g91"},{"pattern":"〜に向けて／〜に向けた","meaning":"toward; aimed at; in preparation for (a goal or event)","formation":"Noun + に向けて + Verb / Noun + に向けた + Noun","note":"Marks a goal you are working toward. 〜に向かって is more about physical direction.","examples":[{"ja":"試験に向けて、毎日三時間勉強している。","en":"I'm studying three hours a day for the exam."},{"ja":"オリンピックに向けた準備が進んでいる。","en":"Preparations for the Olympics are under way."}],"id":"n2g92"},{"pattern":"〜に応えて／〜に応える","meaning":"in response to; living up to (expectations, requests)","formation":"Noun (期待・要望・声 etc.) + に応えて / に応える + Noun","note":"Used with words like 期待, 要望, 声, 求め. Not the same as 〜に応じて (according to; depending on).","examples":[{"ja":"ファンの声に応えて、歌手はもう一曲歌った。","en":"In response to the fans' calls, the singer sang one more song."},{"ja":"親の期待に応えようと、彼は必死に{頑張|がんば}った。","en":"He worked desperately hard to live up to his parents' expectations."}],"id":"n2g93"},{"pattern":"〜に相違ない","meaning":"there is no doubt that; must be (formal)","formation":"Plain form (な-adj / Noun without だ) + に相違ない","note":"A formal, written version of 〜に違いない.","examples":[{"ja":"犯人はこの近くに住んでいる者に相違ない。","en":"The culprit must be someone who lives near here."},{"ja":"これは彼が書いた手紙に相違ない。","en":"There is no doubt that this letter was written by him."}],"id":"n2g94"},{"pattern":"〜ぶり／〜ぶりに","meaning":"for the first time in (a period); the way someone does ~","formation":"Time period + ぶりに / Noun or V-stem + ぶり","note":"三年ぶり = for the first time in three years. 仕事ぶり, 話しぶり describe how someone does something.","examples":[{"ja":"十年ぶりに{故郷|こきょう}に帰った。","en":"I went back to my hometown for the first time in ten years."},{"ja":"彼の真面目な仕事ぶりは、皆に評価されている。","en":"His diligent way of working is appreciated by everyone."}],"id":"n2g95"},{"pattern":"〜づらい","meaning":"hard to ~; awkward to ~ (physically or emotionally)","formation":"V-stem + づらい","note":"Often used when something is hard because it is uncomfortable or emotionally awkward. 〜にくい is more neutral; 〜がたい is very formal.","examples":[{"ja":"この靴は重くて歩きづらい。","en":"These shoes are heavy and hard to walk in."},{"ja":"先生には本当のことが言いづらかった。","en":"It was hard to tell the teacher the truth."}],"id":"n2g96"},{"pattern":"〜ようでは","meaning":"if (you're) like this / if you do ~ (a bad result will follow)","formation":"Plain form + ようでは / ようじゃ + negative result","note":"Criticizes a current attitude or habit and warns of a bad outcome.","examples":[{"ja":"こんな簡単な問題が解けないようでは、合格は無理だ。","en":"If you can't solve a problem this easy, you have no chance of passing."},{"ja":"毎朝遅刻するようでは、信用されないよ。","en":"If you're late every morning, nobody will trust you."}],"id":"n2g97"},{"pattern":"〜ようではないか","meaning":"let's ~ (a formal call to action)","formation":"V-volitional + ではないか / じゃないか","note":"A strong, public invitation to act together, typical of speeches and editorials.","examples":[{"ja":"地球の未来のために、一緒に行動しようではないか。","en":"For the future of the earth, let us act together."},{"ja":"最後まで{諦|あきら}めずに戦おうではないか。","en":"Let us fight on to the end without giving up."}],"id":"n2g98"},{"pattern":"〜こと (rules)","meaning":"must ~; do ~ (written rules and instructions)","formation":"V-dictionary form / V-ない + こと","note":"Ends a sentence in notices, rules and teachers' instructions. Not used in normal conversation.","examples":[{"ja":"レポートは金曜日までに{提出|ていしゅつ}すること。","en":"Hand in the report by Friday."},{"ja":"館内では写真を{撮|と}らないこと。","en":"No photography inside the building."}],"id":"n2g99"},{"pattern":"〜てはいられない","meaning":"can't afford to keep ~ing; can't just stay ~","formation":"V-て + はいられない / V-て + ばかりはいられない","note":"The situation is pressing, so you can't carry on as you are.","examples":[{"ja":"試験まであと一週間だ。遊んではいられない。","en":"The exam is a week away. I can't keep playing around."},{"ja":"失敗したからといって、泣いてばかりはいられない。","en":"Just because I failed, I can't spend all my time crying."}],"id":"n2g100"},{"pattern":"〜に限る","meaning":"~ is the best; nothing beats ~","formation":"Noun / V-dictionary form / V-ない + に限る","note":"The speaker's opinion of the best thing to do. Different from 〜に限って (of all times) and 〜に限り (only).","examples":[{"ja":"暑い日は冷たいビールに限る。","en":"On a hot day, nothing beats a cold beer."},{"ja":"疲れた時は、早く寝るに限る。","en":"When you're tired, the best thing is to go to bed early."}],"id":"n2g101"},{"pattern":"〜ほかない／〜よりほかない","meaning":"have no choice but to ~; can only ~","formation":"V-dictionary form + ほかない / よりほかない / ほかはない","note":"A little more formal than 〜しかない.","examples":[{"ja":"電車が止まったので、歩いて帰るほかない。","en":"The trains have stopped, so I have no choice but to walk home."},{"ja":"{誰|だれ}も手伝ってくれないなら、自分でやるよりほかない。","en":"If nobody will help, I'll just have to do it myself."}],"id":"n2g102"},{"pattern":"〜くらいなら","meaning":"rather than ~ (I'd prefer …)","formation":"V-dictionary form + くらいなら / ぐらいなら + 〜ほうがましだ / 〜ほうがいい","note":"The first option is so bad that the speaker would rather do the second.","examples":[{"ja":"あんな人に頼むくらいなら、自分でやったほうがましだ。","en":"Rather than ask someone like that, I'd be better off doing it myself."},{"ja":"途中でやめるくらいなら、最初からやらないほうがいい。","en":"If you're going to quit halfway, it's better not to start at all."}],"id":"n2g103"},{"pattern":"〜だけのことはある","meaning":"as you'd expect from ~; it's no wonder (praise)","formation":"Plain form (な-adj + な / Noun) + だけのことはある","note":"Admits that a good result matches the effort, price or reputation. Like 〜だけあって, but it ends the sentence.","examples":[{"ja":"彼の日本語は{完璧|かんぺき}だ。十年日本に住んでいただけのことはある。","en":"His Japanese is perfect — just what you'd expect after ten years in Japan."},{"ja":"このかばんはとても{丈夫|じょうぶ}だ。高かっただけのことはある。","en":"This bag is really sturdy. It was worth the high price."}],"id":"n2g104"},{"pattern":"〜ないものか／〜ないものだろうか","meaning":"isn't there some way to ~?; I wish ~ could happen","formation":"V-ない (often potential) + ものか / ものだろうか","note":"A strong wish for something difficult to come true.","examples":[{"ja":"もっと安く旅行できないものか。","en":"Isn't there some way to travel more cheaply?"},{"ja":"何とかして彼を助けられないものだろうか。","en":"Isn't there any way we could help him?"}],"id":"n2g105"},{"pattern":"〜となると／〜となれば","meaning":"when it comes to ~; if it's the case that ~","formation":"Plain form / Noun + となると / となれば / となったら","note":"Introduces a new situation and what would naturally follow from it.","examples":[{"ja":"留学するとなると、お金がかなり必要だ。","en":"If it comes to studying abroad, you'll need quite a lot of money."},{"ja":"社長が来るとなれば、しっかり準備しなければならない。","en":"If the president is coming, we have to prepare properly."}],"id":"n2g106"},{"pattern":"〜としては","meaning":"as far as ~ is concerned; from ~'s standpoint","formation":"Noun (person / organization) + としては","note":"Gives the position or opinion of a person or group. 〜として alone means 'in the role of'.","examples":[{"ja":"私としては、この案に賛成です。","en":"Personally, I'm in favour of this plan."},{"ja":"会社としては、これ以上給料を上げることはできない。","en":"As far as the company is concerned, it can't raise salaries any further."}],"id":"n2g107"},{"pattern":"〜てこそ","meaning":"only by ~ing; it's precisely because you ~ that","formation":"V-て + こそ","note":"Stresses that the result is only possible through the stated action.","examples":[{"ja":"自分でやってみてこそ、本当の難しさがわかる。","en":"Only by trying it yourself do you understand how hard it really is."},{"ja":"苦労してこそ、{成功|せいこう}の喜びは大きくなる。","en":"It's precisely because you struggle that success feels so good."}],"id":"n2g108"},{"pattern":"〜ことは〜が","meaning":"it's true that ~, but …; I did ~, but …","formation":"Plain form + ことは + the same word + が / けど","note":"Admits something only partly or reluctantly; the same verb or adjective is repeated.","examples":[{"ja":"行くことは行くが、少し遅れるかもしれない。","en":"I will go, but I might be a little late."},{"ja":"この本は読んだことは読んだけど、あまり覚えていない。","en":"I did read this book, but I don't remember much of it."}],"id":"n2g109"},{"pattern":"〜は言うまでもなく／〜は言うまでもない","meaning":"not to mention ~; it goes without saying that ~","formation":"Noun + は言うまでもなく / Plain form + のは言うまでもない","note":"The first point is obvious; the speaker adds something more.","examples":[{"ja":"彼は英語は言うまでもなく、中国語も話せる。","en":"He speaks Chinese, not to mention English."},{"ja":"健康が大切なのは言うまでもない。","en":"It goes without saying that health is important."}],"id":"n2g110"},{"pattern":"〜も〜なら〜も","meaning":"~ is as bad as ~; both are to blame","formation":"Noun + も + same Noun + なら + Noun + も + same Noun + だ","note":"Criticizes both sides equally, as in 親も親なら子も子だ.","examples":[{"ja":"親も親なら子も子だ。どちらも{礼儀|れいぎ}を知らない。","en":"The child is no better than the parent — neither has any manners."},{"ja":"売る方も売る方なら、買う方も買う方だ。","en":"The buyer is just as bad as the seller."}],"id":"n2g111"},{"pattern":"〜だの〜だの","meaning":"~ and ~ and so on (a complaining list)","formation":"Noun / Plain form + だの + Noun / Plain form + だの","note":"Lists things, usually with a negative or complaining tone.","examples":[{"ja":"彼女は疲れただの眠いだのと{文句|もんく}ばかり言う。","en":"She does nothing but complain — she's tired, she's sleepy and so on."},{"ja":"部屋には本だの服だのが散らかっている。","en":"Books, clothes and stuff are scattered all over the room."}],"id":"n2g112"},{"pattern":"〜かというと／〜かといえば","meaning":"if you ask whether ~ (well, actually …)","formation":"Question word / Plain form + か + というと / といえば","note":"Raises a question and then answers it, often against the obvious answer: 〜かというと、そうではない.","examples":[{"ja":"高い物が必ずいいかというと、そうでもない。","en":"Are expensive things always good? Not necessarily."},{"ja":"なぜ遅れたかといえば、道が混んでいたからだ。","en":"As for why I was late — the roads were jammed."}],"id":"n2g113"},{"pattern":"〜(よ)うか〜まいか","meaning":"whether to ~ or not (hesitation)","formation":"V-volitional + か + V-dictionary form + まいか","note":"Used with 迷う, 悩む, 考える to show indecision. For する: しようかするまいか.","examples":[{"ja":"留学しようかするまいか、まだ迷っている。","en":"I'm still torn about whether to study abroad."},{"ja":"彼に本当のことを言おうか言うまいか悩んだ。","en":"I agonized over whether or not to tell him the truth."}],"id":"n2g114"},{"pattern":"〜ものと思われる","meaning":"it is thought that ~; presumably (formal)","formation":"Plain form + ものと思われる / ものとみられる","note":"Common in news and formal writing for a careful judgment.","examples":[{"ja":"事故の原因は居眠り運転だったものと思われる。","en":"The accident is thought to have been caused by the driver falling asleep."},{"ja":"台風は明日九州に上陸するものと思われる。","en":"The typhoon is expected to make landfall in Kyushu tomorrow."}],"id":"n2g115"},{"pattern":"〜とされる／〜とされている","meaning":"is considered to be ~; it is said that ~ (formal)","formation":"Plain form / Noun + とされる / とされている","note":"States a generally accepted view or an official position, common in textbooks and the news.","examples":[{"ja":"この寺は日本で最も古い木造建築とされている。","en":"This temple is considered the oldest wooden building in Japan."},{"ja":"{睡眠|すいみん}不足は病気の原因になるとされる。","en":"Lack of sleep is said to cause illness."}],"id":"n2g116"},{"pattern":"〜見込みだ","meaning":"is expected to ~; is likely to ~ (forecast)","formation":"V-dictionary form / Noun + の + 見込みだ; 〜見込みがない = no prospect of ~","note":"Used in news and business for forecasts. 見込みがない means there is no chance.","examples":[{"ja":"新しい駅は来年完成する見込みだ。","en":"The new station is expected to be completed next year."},{"ja":"この病気は治る見込みがない。","en":"There's no prospect of this illness being cured."}],"id":"n2g117"},{"pattern":"〜を前に(して)","meaning":"just before ~; facing ~","formation":"Noun + を前に / を前にして","note":"Used just before an important event, or when standing in front of something or someone.","examples":[{"ja":"試験を前にして、{緊張|きんちょう}で眠れなかった。","en":"With the exam just ahead, I was too nervous to sleep."},{"ja":"大勢の観客を前に、彼は堂々と歌った。","en":"In front of a large audience, he sang with confidence."}],"id":"n2g118"},{"pattern":"〜{拍子|ひょうし}に","meaning":"the moment ~; as ~ (and something happened by accident)","formation":"V-た + 拍子に / Noun + の + 拍子に","note":"Something unexpected happens at the very moment of an action.","examples":[{"ja":"転んだ{拍子|ひょうし}に、{眼鏡|めがね}が落ちて割れた。","en":"When I fell, my glasses dropped and broke."},{"ja":"立ち上がった{拍子|ひょうし}に、机に頭をぶつけた。","en":"As I stood up, I banged my head on the desk."}],"id":"n2g119"},{"pattern":"〜折(に)","meaning":"on the occasion of; when (polite, formal)","formation":"V-dictionary form / V-た + 折(に) / Noun + の + 折(に)","note":"A polite word for 時, often in letters: お近くにお越しの折には …","examples":[{"ja":"京都へ行った折に、昔の友人に会った。","en":"When I went to Kyoto, I met an old friend."},{"ja":"お近くにお越しの折には、ぜひお立ち寄りください。","en":"When you're in the area, please do drop by."}],"id":"n2g120"},{"pattern":"〜を{兼|か}ねて","meaning":"also serving as; combined with (a second purpose)","formation":"Noun + を兼ねて / Noun + を兼ねた + Noun","note":"One action serves two purposes at once.","examples":[{"ja":"運動を{兼|か}ねて、毎朝犬の散歩をしている。","en":"I walk the dog every morning, which doubles as exercise."},{"ja":"{趣味|しゅみ}と{実益|じつえき}を{兼|か}ねたアルバイトを探している。","en":"I'm looking for a part-time job that's both a hobby and a source of income."}],"id":"n2g121"},{"pattern":"〜を除いて／〜を除く","meaning":"except for; excluding","formation":"Noun + を除いて / を除けば / を除く + Noun","note":"A formal version of 〜以外.","examples":[{"ja":"日曜日を除いて、毎日営業しています。","en":"We're open every day except Sunday."},{"ja":"一部の地域を除く全国で雨が降るでしょう。","en":"It will rain nationwide except in some areas."}],"id":"n2g122"},{"pattern":"〜たって／〜だって","meaning":"even if ~ (casual)","formation":"V-た + って / い-adj (〜く) + たって / Noun, な-adj + だって","note":"A casual spoken form of 〜ても / 〜でも.","examples":[{"ja":"いくら頼んだって、彼は手伝ってくれないよ。","en":"No matter how much you ask, he won't help you."},{"ja":"高くたって、欲しいものは買う。","en":"Even if it's expensive, I'll buy what I want."}],"id":"n2g123"},{"pattern":"〜てでも","meaning":"even if it means ~; even by ~ing","formation":"V-て + でも","note":"Strong determination: the speaker is ready to go as far as an extreme action.","examples":[{"ja":"借金をしてでも、この家を買いたい。","en":"I want to buy this house, even if it means taking out a loan."},{"ja":"{徹夜|てつや}してでも、明日までに終わらせる。","en":"I'll finish it by tomorrow, even if I have to stay up all night."}],"id":"n2g124"},{"pattern":"〜ことだし","meaning":"since ~ (among other reasons); seeing as ~","formation":"Plain form (な-adj + な / Noun + である) + ことだし","note":"Gives a light reason, hinting there are others. Usually followed by a suggestion or decision.","examples":[{"ja":"雨もやんだことだし、散歩に行きましょう。","en":"Seeing as the rain has stopped, let's go for a walk."},{"ja":"みんな{揃|そろ}ったことだし、そろそろ始めようか。","en":"Since everyone's here, shall we get started?"}],"id":"n2g125"},{"pattern":"〜なりに／〜なりの","meaning":"in one's own way; as best one can (within limits)","formation":"Noun / Plain form + なりに / なりの + Noun","note":"Admits limits but shows real effort or a reasonable result: 私なりに, 子供なりの考え. Different from the N1 〜なり (as soon as).","examples":[{"ja":"私なりに{一生懸命|いっしょうけんめい}{頑張|がんば}ったつもりです。","en":"I believe I tried my hardest, in my own way."},{"ja":"子供には子供なりの悩みがある。","en":"Children have worries of their own."}],"id":"n2g126"}];